Three causal filters for a noisy scalar signal. All take a plain array and return one of the same length; none looks ahead, so each output matches what the filter would have produced running online, one sample at a time.
VM = window.VM
vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))
chartColors = VM.plotting.colors(vmTheme)
noisy = {
  const rng = VM.sampling.seededRandom(7)
  const gaussian = VM.sampling.gaussianRandom(rng)
  const zs = []
  for (let i = 0; i &lt; 60; i++) zs.push(Math.sin(i / 8) + 0.3 * gaussian())
  return zs
}

The three side by side

viewof filterK = Inputs.range([1, 15], {label: "moving-average window k", step: 1, value: 5})
viewof filterAlpha = Inputs.range([0, 0.99], {label: "EMA alpha", step: 0.01, value: 0.8})
viewof filterQ = Inputs.range([0.0001, 0.1], {label: "Kalman Q", step: 0.0001, value: 0.005})























{
  const ma = VM.filters.movingAverageFilter(noisy, filterK)
  const ema = VM.filters.emaFilter(noisy, filterAlpha)
  const kal = VM.filters.kalman1DFilter(noisy, {R: 0.09, Q: filterQ}).xs
  const c = chartColors   // reactive on the theme, so the lines repaint on a toggle
  const rows = []
  for (let i = 0; i &lt; noisy.length; i++) {
    rows.push({i, series: "measured", y: noisy[i]})
    rows.push({i, series: "moving average", y: ma[i]})
    rows.push({i, series: "EMA", y: ema[i]})
    rows.push({i, series: "Kalman", y: kal[i]})
  }
  return Plot.plot(VM.plotting.plotOptions({
    height: 320,
    x: {label: "sample"}, y: {label: null},
    color: {legend: true, domain: ["measured", "moving average", "EMA", "Kalman"], range: [c.muted, c.alt, c.ok, c.fn]},
    marks: [
      Plot.dot(rows.filter(d =&gt; d.series === "measured"), {x: "i", y: "y", stroke: "series", r: 2}),
      Plot.line(rows.filter(d =&gt; d.series !== "measured"), {x: "i", y: "y", stroke: "series", strokeWidth: 2})
    ]
  }))
}

The fields, tagged
Each targetable field gets a stable data-example-field attribute from the cell that creates it. The text fields also submit on Enter by clicking the button – found by its own tag, not by a reactive reference.


viewof exF = {
  const view = Inputs.text({label: "f(x)", value: "sin(x)"})
  view.dataset.exampleField = "f"
  view.classList.add("ojs-fill")
  view.addEventListener("keydown", e =&gt; { if (e.key === "Enter") document.querySelector('[data-example-field="plot"] button')?.click() })
  return view
}







viewof exLo = {
  const view = Inputs.text({label: "from", value: "-6"})
  view.dataset.exampleField = "lo"
  return view
}







viewof exHi = {
  const view = Inputs.text({label: "to", value: "6"})
  view.dataset.exampleField = "hi"
  return view
}







viewof exPlot = {
  const view = Inputs.button("Plot")
  view.dataset.exampleField = "plot"
  return view
}

Commit on click
The result cell depends on the button’s click count and reads the fields through their views (viewof exF.value), which is not a reactive dependency on their values – so typing doesn’t redraw; clicking does.

committed = {
  exPlot   // the click count: this cell re-runs on each click and on nothing else
  return {f: viewof exF.value, lo: viewof exLo.value, hi: viewof exHi.value}
}

The dropdown
Two rules, both from applyExampleParams’s own contract:

Selectors, not viewof references. A cell that references a view whose element gets recreated becomes reactive on it; since applying an example is what recreates downstream views, a direct-reference version re-triggers itself without end.
One DOM listener, not a reactive cell. A &lt;select&gt; fires input and change per pick; a cell reactive on its value runs twice and the two overlapping applications race. The cell below creates the &lt;select&gt; and attaches a single listener; it depends on nothing reactive, so it never re-runs.


examples = [
  {label: "sine on a period", params: {f: "sin(x)", lo: "0", hi: "2pi"}},
  {label: "damped oscillation", params: {f: "e^(-x/4) cos(3x)", lo: "0", hi: "12"}},
  {label: "runge's function", params: {f: "1/(1 + 25x^2)", lo: "-1", hi: "1"}},
  {label: "a pole", params: {f: "1/(x - 1)", lo: "-2", hi: "4"}}
]







fieldSelectors = ({
  f: '[data-example-field="f"]',
  lo: '[data-example-field="lo"]',
  hi: '[data-example-field="hi"]'
})







{
  const select = document.createElement("select")
  select.className = "form-select form-select-sm"
  select.style.maxWidth = "22em"
  select.setAttribute("aria-label", "Try an example")
  const first = document.createElement("option")
  first.textContent = "Try an example…"
  first.value = ""
  select.appendChild(first)
  for (let i = 0; i &lt; examples.length; i++) {
    const option = document.createElement("option")
    option.value = String(i)
    option.textContent = examples[i].label
    select.appendChild(option)
  }
  select.addEventListener("change", () =&gt; {
    if (select.value === "") return
    const example = examples[Number(select.value)]
    const trigger = document.querySelector('[data-example-field="plot"]')
    VM.ui.applyExampleParams(fieldSelectors, example.params, trigger)
    select.value = ""
  })
  return select
}

The chart


{
  const f = VM.expressions.makeFunction(math, committed.f)
  const lo = VM.expressions.makeNumber(math, committed.lo)
  const hi = VM.expressions.makeNumber(math, committed.hi)
  const ok = f !== null && lo !== null && hi !== null && hi &gt; lo
